/*********************************************************************************************************
     METODOLOGÍA PARA LA CLASIFICACIÓN DE CICATRICES DE FUEGO CON BASE A IMAGENES ÓPTICAS Y DE RADAR
     Script actualizado a diciembre 2024       
-------------------------------------------------------------------------------------------------------
Fuente de información con imágenes históricos de LANDSAT (LANDSAT 8 y 9) y Sentinel 1 y 2.   
  
Script adaptado por el departamento de Sistemas de Información Geográfica del Instituto Nacional de Bosques:
Danger Gómez, Javier Montes, Manuel Custodio
 
Consejo Nacional de Áreas Protegidas -CONAP-: Marlin George 
 
Apoyo especial: 
Emil Cherrington, Betsy Hernández (SERVIR - NASA)

Con la colaboración del GIMBUT (INAB, CONAP, MARN, MAGA, UVG, URL, USAC) e información de NASA - ARSET 
en el Mapeo y Monitoreo de los Bosques con Datos SAR 
https://arset.gsfc.nasa.gov/land/webinars/bosques-sar 

Utilizando como base la metodología de SIGMA I.
 
Nuestro objetivo general es clasificar las categorías de cicatriz y de no cicatriz de fuego del territorio de la república de Guatemala. 

******************************************************************************************************/
/* 
VARIABLES
1- Área de interés para hacer la clasificación. Buffer de 1 kilómetro de la república de Guatemala.
2- Período para imágenes RADAR y OPTICAS inicio de período
3- Período para imágenes RADAR y OPTICAS final del período
4- Ruta de muestras subidas a "Assets" (columna = Class [tipo entero])
    Las clases a trabajar son las categorías del IPCC [6 cateogrías] [Proyección geográfica]
5- Color de las muestras
6- Colección de imágenes
7- Porcentaje de nubosidad
8- El valor de percentil
9- Porcentaje de nubosidad
10- Un límite aproximado de la cantidad máxima
11- Escala de visualización
*/
  
//====================================================================================================
//*********************************************FUENTE************************************************* 
//====================================================================================================
// IMAGENES DE SATELITE:    
// LANDSAT 9           |         LANDSAT 8          |        SENTINEL 1 y 2
//....................................................................................................
// Regiones REDD+
// COBERTURA VEGETAL Y USO DE LA TIERRA, AÑO 2020. REPUBLICA DE GUATEMALA A ESCALA: 1:1,700,000
// (1. Territorios Artificializados) MAGA, 2020.
//....................................................................................................

//========================================================================================================
//*************************** FUNCIONES PARA LAS COLECCIONES DE IMAGENES *********************************
//****************** LANDSAT 8 ***** LANDSAT 9 ***** LANDSAT 8 9 ***** SENTINEL 2 ************************

//NOTA: DIRIGIRSE A LA LINEA 198 para ingresar información

// Función para Landsat 8
function landsat8(startDate, endDate) {
  return ee.ImageCollection("LANDSAT/LC08/C02/T1_L2")
    .filterDate(ee.Date(startDate), ee.Date(endDate))
    .filter(ee.Filter.inList('WRS_PATH', [19, 20, 21]))
    .filter(ee.Filter.inList('WRS_ROW', [48, 49, 50]))
    .map(function(img) {
      var qa = img.select('QA_PIXEL');
      var cloudShadowBitMask = ee.Number(2).pow(3).int(); // Bit 3 (sombra de nubes)
      var cloudsBitMask = ee.Number(2).pow(4).int();      // Bit 4 (nubes)
      var mask = qa.bitwiseAnd(cloudShadowBitMask).eq(0)
                  .and(qa.bitwiseAnd(cloudsBitMask).eq(0));
      return img.updateMask(mask);
    })
    .select('SR_B.')
    .map(function(img) {
      return img.multiply(0.0000275).add(-0.2).multiply(10000)
                .select(['SR_B2', 'SR_B3', 'SR_B4', 'SR_B5', 'SR_B6', 'SR_B7'], 
                        ['B_1', 'B_2', 'B_3', 'B_4', 'B_5', 'B_7']);
    })
    .median()
    .toUint16()
    .clip(aoiGT);
}
 
// Función para Landsat 9
function landsat9(startDate, endDate) {
  return ee.ImageCollection("LANDSAT/LC09/C02/T1_L2")
    .filterDate(ee.Date(startDate), ee.Date(endDate))
    .filter(ee.Filter.inList('WRS_PATH', [19, 20, 21]))
    .filter(ee.Filter.inList('WRS_ROW', [48, 49, 50]))
    .map(function(img) {
      var qa = img.select('QA_PIXEL');
      var cloudShadowBitMask = ee.Number(2).pow(3).int(); // Bit 3 (sombra de nubes)
      var cloudsBitMask = ee.Number(2).pow(4).int();      // Bit 4 (nubes)
      var mask = qa.bitwiseAnd(cloudShadowBitMask).eq(0)
                  .and(qa.bitwiseAnd(cloudsBitMask).eq(0));
      return img.updateMask(mask);
    })
    .select('SR_B.')
    .map(function(img) {
      return img.multiply(0.0000275).add(-0.2).multiply(10000)
                .select(['SR_B2', 'SR_B3', 'SR_B4', 'SR_B5', 'SR_B6', 'SR_B7'], 
                        ['B_1', 'B_2', 'B_3', 'B_4', 'B_5', 'B_7']);
    })
    .median()
    .toUint16()
    .clip(aoiGT);
}
 
// Combinación de Landsat 8 y Landsat 9
function gt_l8_l9(startDate, endDate) {
  return ee.ImageCollection("LANDSAT/LC08/C02/T1_L2")
    .merge(ee.ImageCollection("LANDSAT/LC09/C02/T1_L2"))
    .filterDate(ee.Date(startDate), ee.Date(endDate))
    .filter(ee.Filter.inList('WRS_PATH', [19, 20, 21]))
    .filter(ee.Filter.inList('WRS_ROW', [48, 49, 50]))
    .map(function(img) {
      var qa = img.select('QA_PIXEL');
      var cloudShadowBitMask = ee.Number(2).pow(3).int(); // Bit 3 (sombra de nubes)
      var cloudsBitMask = ee.Number(2).pow(4).int();      // Bit 4 (nubes)
      var mask = qa.bitwiseAnd(cloudShadowBitMask).eq(0)
                  .and(qa.bitwiseAnd(cloudsBitMask).eq(0));
      return img.updateMask(mask);
    })
    .select('SR_B.')
    .map(function(img) {
      return img.multiply(0.0000275).add(-0.2).multiply(10000)
                .select(['SR_B2', 'SR_B3', 'SR_B4', 'SR_B5', 'SR_B6', 'SR_B7'], 
                        ['B_1', 'B_2', 'B_3', 'B_4', 'B_5', 'B_7']);
    })
    .median()
    .toUint16()
    .clip(aoiGT);
}

// Función para Sentinel-2 armonizado
function maskS2Aggressive(image) {
  var qa = image.select('QA60');
  var scl = image.select('SCL');

  // Bits 10 and 11 are clouds and cirrus, respectively.
  var cloudBitMask = 0 << 10;
  var cirrusBitMask = 0 << 11;

  // Mask for clear sky based on QA60
  var maskQA = qa.bitwiseAnd(cloudBitMask).eq(0)
      .and(qa.bitwiseAnd(cirrusBitMask).eq(0));

  // Mask for clear conditions based on SCL
  var maskSCL = scl.neq(3)           // No shadows
                   //.and(scl.neq(7))
                   .and(scl.neq(8))  // No medium clouds
                   .and(scl.neq(9))  // No high clouds
                   .and(scl.neq(10)) // No thick clouds
                  // .and(scl.neq(11)); // No high aerosols

  return image.updateMask(maskQA).updateMask(maskSCL);
}

// Función para Sentinel-2 armonizado con enmascaramiento agresivo
function sentinel2(startDate, endDate) {
  var s2Sr = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED');

  // Filtrar colecciones por fecha y región
  var criteria = ee.Filter.and(
      ee.Filter.bounds(aoiGT), ee.Filter.lt("CLOUDY_PIXEL_PERCENTAGE", 75), ee.Filter.date(ee.Date(startDate), ee.Date(endDate)));

  s2Sr = s2Sr.filter(criteria).map(maskS2Aggressive).sort('system:time_start');

  // Aplicar enmascaramiento agresivo y devolver la imagen mediana con bandas renombradas
  return s2Sr
    .select(['B2', 'B3', 'B4', 'B8', 'B11', 'B12'], ['B_1', 'B_2', 'B_3', 'B_4', 'B_5', 'B_7'])
    .mosaic()
    .toUint16()
    .clip(aoiGT);
}
 
//========================================================================================================
// Función para eliminar los poblados del mosaico o imagen
var eliminarPoblados = function(image){
  // Crear una imagen enmascarada con los límites de poblados
  var pobladosMask = ee.Image.constant(0).clipToCollection(poblados).mask();
  // Devolver la imagen original con los poblados enmascarados (eliminados)
  return image.updateMask(pobladosMask.not());
};

// Función para crear el mosaico a partir de fechas y el satélite especificado
function createMosaicFromSatellite(startDate, endDate, satelite) {
  var image;
  if (satelite === 'Sentinel2') {
    image = sentinel2(startDate, endDate);
  } else if (satelite === 'Landsat9') {
    image = landsat9(startDate, endDate);
  } else if (satelite === 'Landsat8_9') {
    image = gt_l8_l9(startDate, endDate);
  } else {
    throw new Error('Satélite no reconocido. Use "Landsat8", "Landsat9", "Landsat8_9", o "Sentinel2".');
  }
  return eliminarPoblados(image);
}
//========================================================================================================
 
//========================================================================================================
//********************************** PARAMETROS DE ENTRADA ***********************************************
var training = cicatriz.merge(nocicatriz);
var fechaInicial =        '2026-05-16'; // Fecha inicial
var fechaFinal =          '2026-05-31';   // Fecha final
var fechaInicialSAR =     '2026-05-16';
var fechaFinalSAR   =     '2026-05-31';
//var MAX_CLOUD_PROBABILITY = 70;  // Probabilidad máxima de nubes para Sentinel 2
var satelite =            'Sentinel2';      // Puede ser Landsat8, Landsat9,'Landsat8_9' o 'Sentinel2'

var ID1 = 1;
var ID2 = 2;
var ID3 = 3;
var ID4 = 4;
var ID5 = 5;

var buffer1 = redd1.filter(ee.Filter.eq('id', ID1))
                  .map(function(feature){
                    return feature.setGeometry(feature.geometry().simplify(100).buffer(1000));
                  });

var buffer2 = redd1.filter(ee.Filter.eq('id', ID2))
                  .map(function(feature){
                    return feature.setGeometry(feature.geometry().simplify(100).buffer(1000));
                  });
                  
var buffer3 = redd1.filter(ee.Filter.eq('id', ID3))
                  .map(function(feature){
                    return feature.setGeometry(feature.geometry().simplify(100).buffer(1000));
                  });
                  
var buffer4 = redd1.filter(ee.Filter.eq('id', ID4))
                  .map(function(feature){
                    return feature.setGeometry(feature.geometry().simplify(100).buffer(1000));
                  });
                  
var buffer5 = redd1.filter(ee.Filter.eq('id', ID5))
                  .map(function(feature){
                    return feature.setGeometry(feature.geometry().simplify(100).buffer(1000));
                  });
//========================================================================================================
 
// PARAMETROS DE VISUALIZACIÓN
var imgParam = {bands: ['B_7', 'B_5', 'B_4'], min: 0, max: 3000};
//paleta de colores NDVI
var PaletaNDVI = {"opacity":1,"bands":["NDVI"],"min":0.11489361524581909,"max":0.826943576335907,"palette":["ff1212","ffa85e","fdff7a","dcffa5","5cf37c","1f9928"]};
var PaletaNDWBI = {"opacity":1,"bands":["NDWBI"],"min":-0.7719128131866455,"max":-0.19809767603874207,"palette":["3dab3b","44e96f","7aff62","ffe770","ff8b39","ff3d1d"]};
var PaletaNDWI = {"opacity":1,"bands":["NDWI"],"min":-0.300235390663147,"max":0.3715430796146393,"palette":["ff1818","ffc2a5","fdff8b","afff85","28af18"]};
var PaletaNBR = {"opacity":1,"bands":["NBR"],"min":-0.2935761511325836,"max":0.6659053564071655,"palette":["d00303","fd3a00","ff9b6c","f4ff54","d4ff80","52ff27","38bc3c"]};

// Crear Mosaico
var mosaico = createMosaicFromSatellite(fechaInicial, fechaFinal, satelite);
var mosaicoR1 = mosaico.clip(buffer1);
var mosaicoR2 = mosaico.clip(buffer2);
var mosaicoR3 = mosaico.clip(buffer3);
var mosaicoR4 = mosaico.clip(buffer4);
var mosaicoR5 = mosaico.clip(buffer5);

// Elaboración de indices imagen1
var ndvi1  = mosaico.normalizedDifference(['B_4', 'B_3']).rename('NDVI');
var ndwbi1 = mosaico.normalizedDifference(['B_2', 'B_4']).rename('NDWBI');
var ndwi1  = mosaico.normalizedDifference(['B_4', 'B_5']).rename('NDWI');
var nbr1   = mosaico.normalizedDifference(['B_4', 'B_7']).rename('NBR');


Map.addLayer(aoiGT, {}, 'Límite de Guate con 1km de buffer', 0);

//Map.addLayer(buffer1.style({color: 'red', fillColor:'00000000', width:2}),{}, 'Región Petén',0);
// Map.addLayer(buffer2.style({color: 'red', fillColor:'00000000', width:2}),{}, 'Región Occidente',0);

Map.addLayer(mosaico, imageVisParam, 'Mosaico ' + satelite);
