// Map.addLayer(mosaicoR5, imgParam, 'Mosaico Región 5 Costa Sur',0);
Map.addLayer(redd1.style ({color: 'black', fillColor:'00000000', width:2}),{}, 'Regiones REDD+ GT');
Map.addLayer(ndvi1,PaletaNDVI,'NDVI',0);
Map.addLayer(ndwbi1,PaletaNDWBI,'NDWBI',0);
Map.addLayer(ndwi1,PaletaNDWI,'NDWI',0);
Map.addLayer(nbr1,PaletaNBR,'NBR',0);

Map.centerObject(aoiGT, 8);

