//************************ COLECCION DE IMAGENES SENTINEL 1 SAR ******************************************
// Definición de Parámetros Comunes
var INSTRUMENT_MODE = 'IW';
var POLARIZATION_VV = 'VV';
var POLARIZATION_VH = 'VH';
var ORBIT_PASS = 'DESCENDING';
var RESOLUTION_METERS = 10;
var SMOOTHING_RADIUS = 50;

// Cargar y filtrar colección de Sentinel-1
var collection = ee.ImageCollection('COPERNICUS/S1_GRD')
  .filter(ee.Filter.eq('instrumentMode', INSTRUMENT_MODE))
  .filter(ee.Filter.eq('orbitProperties_pass', ORBIT_PASS))
  .filterMetadata('resolution_meters', 'equals', RESOLUTION_METERS)
  .filterBounds(aoiGT)
  .filterDate(fechaInicialSAR, fechaFinalSAR);

print(collection, 'Sentinel-1 Collection');

// Seleccionar bandas y crear mosaicos para el mosaico general 
var SARVV = collection.select(POLARIZATION_VV).mosaic().clip(aoiGT);
var SARVH = collection.select(POLARIZATION_VH).mosaic().clip(aoiGT);

// Visualizar las imágenes SAR originales general
Map.addLayer(SARVV, {min: -15, max: 0}, 'SAR VV', 0);
Map.addLayer(SARVH, {min: -25, max: 0}, 'SAR VH', 0);

// Aplicar filtro de moteado a las imágenes SAR general
var SARVV_filtered = SARVV.focal_mean(SMOOTHING_RADIUS, 'circle', 'meters');
var SARVH_filtered = SARVH.focal_mean(SMOOTHING_RADIUS, 'circle', 'meters');

// Visualizar las imágenes SAR filtradas
Map.addLayer(SARVV_filtered, {min: -15, max: 0}, 'SAR VV Filtered', 0);
Map.addLayer(SARVH_filtered, {min: -25, max: 0}, 'SAR VH Filtered', 0);
//========================================================================================================


//====================================================================================================
//********************************** 6.CLASIFICACIÓN OPTICA ******************************************
//====================================================================================================
//composisión de mosaico 
var composite1 = ee.Image.cat(mosaico,ndvi1,ndwbi1,ndwi1,nbr1);
var compositeR1 = ee.Image.cat(mosaicoR1,ndvi1,ndwbi1,ndwi1,nbr1);
var compositeR2 = ee.Image.cat(mosaicoR2,ndvi1,ndwbi1,ndwi1,nbr1);
var compositeR3 = ee.Image.cat(mosaicoR3,ndvi1,ndwbi1,ndwi1,nbr1);
var compositeR4 = ee.Image.cat(mosaicoR4,ndvi1,ndwbi1,ndwi1,nbr1);
var compositeR5 = ee.Image.cat(mosaicoR5,ndvi1,ndwbi1,ndwi1,nbr1);

var bands_opt = ['B_2', 'B_3', 'B_4', 'B_5', 'B_7', 'NDVI', 'NDWBI', 'NDWI','NBR'];

var training_opt = composite1.select(bands_opt).sampleRegions({
collection: training,
properties: ['id'],
scale: 10 });

var training_optR1 = compositeR1.select(bands_opt).sampleRegions({
collection: training,
properties: ['id'],
scale: 10 });

var training_optR2 = compositeR2.select(bands_opt).sampleRegions({
collection: training,
properties: ['id'],
scale: 10 });

var training_optR3 = compositeR3.select(bands_opt).sampleRegions({
collection: training,
properties: ['id'],
scale: 10 });

var training_optR4 = compositeR4.select(bands_opt).sampleRegions({
collection: training,
properties: ['id'],
scale: 10 });

var training_optR5 = compositeR5.select(bands_opt).sampleRegions({
collection: training,
properties: ['id'],
scale: 10 });

//Train the classifier
var classifier_opt = ee.Classifier.smileRandomForest(30).train({
      features: training_opt,
      classProperty: 'id',
    inputProperties: bands_opt
});

//Train the classifier
var classifier_optR1 = ee.Classifier.smileRandomForest(30).train({
      features: training_optR1,
      classProperty: 'id',
    inputProperties: bands_opt
});

//Train the classifier
var classifier_optR2 = ee.Classifier.smileRandomForest(30).train({
      features: training_optR2,
      classProperty: 'id',
    inputProperties: bands_opt
});

var classifier_optR3 = ee.Classifier.smileRandomForest(30).train({
      features: training_optR3,
      classProperty: 'id',
    inputProperties: bands_opt
});

var classifier_optR4 = ee.Classifier.smileRandomForest(30).train({
      features: training_optR4,
      classProperty: 'id',
    inputProperties: bands_opt
});

var classifier_optR5 = ee.Classifier.smileRandomForest(30).train({
      features: training_optR5,
      classProperty: 'id',
    inputProperties: bands_opt
});

//Run the Classification
var classifiedboth_op = composite1.select(bands_opt).classify(classifier_opt);

var classifiedboth_opR1 = compositeR1.select(bands_opt).classify(classifier_optR1);
var classifiedboth_opR2 = compositeR2.select(bands_opt).classify(classifier_optR2);
var classifiedboth_opR3 = compositeR3.select(bands_opt).classify(classifier_optR3);
var classifiedboth_opR4 = compositeR4.select(bands_opt).classify(classifier_optR4);
var classifiedboth_opR5 = compositeR5.select(bands_opt).classify(classifier_optR5);

//Display the Classification
Map.addLayer(classifiedboth_op, {min: 1, max: 2,  palette:["red","yellow"]},  'Cicatrices de fuego OPTICA Nacional');
